using System.IO.Compression;
using System.Net;
using System.Net.Http;
using System.Security.Cryptography;
using System.Text;
using Hifc.Web.Client;
using Hifc.Web.Contracts;
using Hifc.Web.Update;

if(args.Length==2&&args[0]=="--export-launch-fixture"){PlatformLaunchCases.ExportInterop(args[1]);return 0;}

int passed = 0, failed = 0;
void Test(string name, Action action) { try { action(); passed++; Console.WriteLine("PASS " + name); } catch (Exception ex) { failed++; Console.WriteLine("FAIL " + name + ": " + ex); } }
void Require(bool value, string message) { if (!value) throw new Exception(message); }
void Reject(Action action) { try { action(); } catch (InvalidOperationException) { return; } throw new Exception("Unsafe input accepted"); }
using var rsa = RSA.Create(2048);
var parameters = rsa.ExportParameters(false);
var key = new PublicSigningKey { Modulus = Convert.ToBase64String(parameters.Modulus), Exponent = Convert.ToBase64String(parameters.Exponent) };
byte[] Zip(params (string Name, string Text, int Attributes)[] entries) { using var output = new MemoryStream(); using (var zip = new ZipArchive(output, ZipArchiveMode.Create, true)) foreach (var item in entries) { var e = zip.CreateEntry(item.Name); e.ExternalAttributes = item.Attributes; using var writer = new StreamWriter(e.Open()); writer.Write(item.Text); } return output.ToArray(); }
var bytes = Zip(("node.exe", "runtime", 0));
ComponentLock Lock(byte[] archive, string version = "25.4.0") => new() { MainReleaseId = "0.5.0-dev-20261029T000000Z", MainSourceCommit = new string('a', 40), ComponentId = "node", Version = version, ProtocolMajor = 3, ArchiveSha256 = Convert.ToHexString(SHA256.HashData(archive)).ToLowerInvariant(), ArchiveLength = archive.Length, EntryPoint = "node.exe" };
SignedComponentManifest Sign(ComponentLock item) { var manifest = new SignedComponentManifest { Lock = item, ArchiveUrl = ComponentTrust.ManifestUri(new Uri(UpdateTrust.Server), item).AbsoluteUri.Replace("/manifest", "/archive.zip") }; manifest.Signature = Convert.ToBase64String(rsa.SignData(Encoding.UTF8.GetBytes(ComponentTrust.Payload(manifest)), HashAlgorithmName.SHA256, RSASignaturePadding.Pkcs1)); return manifest; }
var temp = Path.Combine(Path.GetTempPath(), "hifc-component-tests-" + Guid.NewGuid().ToString("N")); Directory.CreateDirectory(temp);
try {
Test("signed component is independently domain bound", () => { var value = Sign(Lock(bytes)); Require(ComponentTrust.Payload(value).StartsWith("HIFC-WEB-COMPONENT-1\n"), "wrong signing domain"); ComponentTrust.Validate(value, value.Lock, key, new Uri(UpdateTrust.Server)); value.Signature = Convert.ToBase64String(rsa.SignData(Encoding.UTF8.GetBytes("HIFC-WEB-UPDATE-1"), HashAlgorithmName.SHA256, RSASignaturePadding.Pkcs1)); Reject(() => ComponentTrust.Validate(value, value.Lock, key, new Uri(UpdateTrust.Server))); });
Test("main release source component version protocol and archive are locked", () => { foreach (var change in new Action<ComponentLock>[] { x => x.MainReleaseId = "0.5.0-dev-20261029T000001Z", x => x.MainSourceCommit = new string('b', 40), x => x.ComponentId = "other", x => x.Version = "26.0.0", x => x.ProtocolMajor = 1, x => x.ArchiveSha256 = new string('b',64), x => x.ArchiveLength++, x => x.RuntimeIdentifier = "linux-x64", x => x.EntryPoint = "other.exe" }) { var expected = Lock(bytes); var value = Sign(Lock(bytes)); change(value.Lock); value = Sign(value.Lock); Reject(() => ComponentTrust.Validate(value, expected, key, new Uri(UpdateTrust.Server))); } });
Test("component archive must use exact HTTPS same-origin URL", () => { foreach (var url in new[] { "http://192.168.6.45:8443/file", "https://example.org/file", "https://192.168.6.45:8443/components/other", "https://user@192.168.6.45:8443/file" }) { var value = Sign(Lock(bytes)); value.ArchiveUrl = url; value.Signature = Convert.ToBase64String(rsa.SignData(Encoding.UTF8.GetBytes(ComponentTrust.Payload(value)),HashAlgorithmName.SHA256,RSASignaturePadding.Pkcs1)); Reject(() => ComponentTrust.Validate(value, value.Lock, key,new Uri(UpdateTrust.Server))); } });
Test("successful preparation is offline usable and detects payload tampering", () => { var item = Lock(bytes); var handler = new FakeHandler(Sign(item), bytes); using var manager = new ComponentManager(Path.Combine(temp,"offline"), new Uri(UpdateTrust.Server), key, handler); var install = manager.PrepareAsync(item,CancellationToken.None).GetAwaiter().GetResult(); Require(File.ReadAllText(install.EntryPoint)=="runtime","payload missing"); handler.Fail=true; Require(manager.PrepareAsync(item,CancellationToken.None).GetAwaiter().GetResult().Directory==install.Directory,"offline unavailable"); File.WriteAllText(install.EntryPoint,"changed"); Reject(() => manager.GetInstalled(item)); });
Test("same component bytes bound to a new main release install independently",()=> { var item=Lock(bytes); var handler=new FakeHandler(Sign(item),bytes); using var manager=new ComponentManager(Path.Combine(temp,"newrelease"),new Uri(UpdateTrust.Server),key,handler); var first=manager.PrepareAsync(item,CancellationToken.None).GetAwaiter().GetResult(); var next=Lock(bytes); next.MainReleaseId="0.5.0-dev-20261029T000001Z"; handler.Manifest=Sign(next); var second=manager.PrepareAsync(next,CancellationToken.None).GetAwaiter().GetResult(); Require(first.Directory!=second.Directory,"main release binding reused"); Require(manager.GetInstalled(item)!=null,"old worker runtime invalidated"); });
Test("archive traversal duplicate Windows aliases links and size limits are refused", () => { int n=0; foreach(var archive in new[] { Zip(("../outside.exe","bad",0)), Zip(("C:/outside.exe","bad",0)), Zip(("node.exe","one",0),("NODE.EXE","two",0)), Zip(("node.exe.","bad",0)), Zip(("CON.exe","bad",0)), Zip(("node.exe","target",unchecked((int)0xA1FF0000))), Zip(("node.exe","target",0x400)), Zip(("node.exe",new string('x',256),0)) }) { var item=Lock(archive); using var manager=new ComponentManager(Path.Combine(temp,"unsafe"+n++),new Uri(UpdateTrust.Server),key,new FakeHandler(Sign(item),archive)) { MaximumExpandedBytes=128 }; Reject(()=>manager.PrepareAsync(item,CancellationToken.None).GetAwaiter().GetResult()); } });
Test("entry count limits are enforced before activation",()=> { var archive=Zip(("node.exe","runtime",0),("extra","content",0)); var item=Lock(archive); using var manager=new ComponentManager(Path.Combine(temp,"count"),new Uri(UpdateTrust.Server),key,new FakeHandler(Sign(item),archive)) { MaximumEntries=1 }; Reject(()=>manager.PrepareAsync(item,CancellationToken.None).GetAwaiter().GetResult()); });
Test("archive parent file collisions and reserved metadata directories are refused",()=> {int n=0;foreach(var archive in new[]{Zip(("node.exe","file",0),("node.exe/child","bad",0)),Zip((".hifc-manifest.json/child","bad",0),("node.exe","runtime",0)),Zip((".hifc-archive.zip/child","bad",0),("node.exe","runtime",0))}){var item=Lock(archive);using var manager=new ComponentManager(Path.Combine(temp,"collision"+n++),new Uri(UpdateTrust.Server),key,new FakeHandler(Sign(item),archive));Reject(()=>manager.PrepareAsync(item,CancellationToken.None).GetAwaiter().GetResult());}});
Test("interrupted wrong hash oversized and redirected downloads retain old runtime",()=> { var root=Path.Combine(temp,"failed"); var old=Lock(bytes); var handler=new FakeHandler(Sign(old),bytes); using var manager=new ComponentManager(root,new Uri(UpdateTrust.Server),key,handler); var first=manager.PrepareAsync(old,CancellationToken.None).GetAwaiter().GetResult(); foreach(var mode in new[]{"short","hash","oversize","redirect"}) { var next=Lock(bytes,"25.4.1"); handler.Manifest=Sign(next); handler.Mode=mode; Reject(()=>manager.PrepareAsync(next,CancellationToken.None).GetAwaiter().GetResult()); Require(File.ReadAllText(first.EntryPoint)=="runtime","old runtime removed"); Require(manager.GetInstalled(old)!=null,"old installation invalidated"); } });
Test("simultaneous preparations publish one immutable runtime",()=> { var item=Lock(bytes); var root=Path.Combine(temp,"concurrent"); using var one=new ComponentManager(root,new Uri(UpdateTrust.Server),key,new FakeHandler(Sign(item),bytes)); using var two=new ComponentManager(root,new Uri(UpdateTrust.Server),key,new FakeHandler(Sign(item),bytes)); var installs=Task.WhenAll(one.PrepareAsync(item,CancellationToken.None),two.PrepareAsync(item,CancellationToken.None)).GetAwaiter().GetResult(); Require(installs[0].Directory==installs[1].Directory,"different activation"); Require(Directory.GetDirectories(Path.Combine(root,"components"),".staging-*",SearchOption.TopDirectoryOnly).Length==0,"staging remains"); });
Test("cancellation does not activate incomplete runtime",()=> { var item=Lock(bytes); using var manager=new ComponentManager(Path.Combine(temp,"cancel"),new Uri(UpdateTrust.Server),key,new FakeHandler(Sign(item),bytes)); using var cancellation=new CancellationTokenSource(); cancellation.Cancel(); try { manager.PrepareAsync(item,cancellation.Token).GetAwaiter().GetResult(); throw new Exception("cancel ignored"); } catch(OperationCanceledException){} Require(manager.GetInstalled(item)==null,"cancel activated"); });
Test("candidate package can prepare before activation and failed components retain old entry",()=> {
 var root=Path.Combine(temp,"candidate");var directory=Path.Combine(root,"versions","candidate");Directory.CreateDirectory(directory);var node=Lock(bytes);var sync=Lock(bytes);sync.ComponentId="platform-sync";sync.Version="0.2.1-web.1";sync.EntryPoint="dist/src/cli.js";var locks=new[]{node,sync};
 ClientPackageInfo Package(string release)=>new(){Version="0.5.0-Web",AddInId=UpdateTrust.AddInId,ReleaseId=release,SourceCommit=node.MainSourceCommit,Files=UpdateTrust.PayloadNames.Select(n=>new ClientPackageFile{Name=n,Length=1,Sha256=new string('a',64)}).ToArray()};
 var active=Path.Combine(root,"package.json");var original=JsonWire.Serialize(Package("0.5.0-dev-20261028T000000Z"));File.WriteAllText(active,original);var manifest=Path.Combine(root,"current.addin");File.WriteAllText(manifest,"old-current-entry");var candidate=Path.Combine(directory,"package.json");File.WriteAllText(candidate,JsonWire.Serialize(Package(node.MainReleaseId)));
 ComponentLocks.ValidatePackage(locks,root,candidate);Reject(()=>ComponentLocks.ValidatePackage(locks,root));var outside=Path.Combine(temp,"outside-package.json");File.WriteAllText(outside,File.ReadAllText(candidate));Reject(()=>ComponentLocks.ValidatePackage(locks,root,outside));
 using(var manager=new ComponentManager(root,new Uri(UpdateTrust.Server),key,new FakeHandler(Sign(node),bytes){Fail=true}))Reject(()=>manager.PrepareAsync(node,CancellationToken.None).GetAwaiter().GetResult());Require(File.ReadAllText(active)==original&&File.ReadAllText(manifest)=="old-current-entry","failed component preparation activated candidate metadata");
});
Test("stalled response body is bounded by preparation timeout",()=> { var item=Lock(bytes); using var manager=new ComponentManager(Path.Combine(temp,"stall"),new Uri(UpdateTrust.Server),key,new FakeHandler(Sign(item),bytes) { Mode="stall" }) { PreparationTimeout=TimeSpan.FromMilliseconds(100) }; using var cancellation=new CancellationTokenSource(TimeSpan.FromSeconds(2)); var clock=System.Diagnostics.Stopwatch.StartNew(); try {manager.PrepareAsync(item,cancellation.Token).GetAwaiter().GetResult();throw new Exception("stalled stream accepted");}catch(OperationCanceledException){} Require(clock.ElapsedMilliseconds<1000,"response body ignored timeout"); Require(manager.GetInstalled(item)==null,"stalled body activated"); });
Test("partial stream interruption preserves prior runtime and removes staging",()=> {var item=Lock(bytes);var root=Path.Combine(temp,"partial");var handler=new FakeHandler(Sign(item),bytes);using var manager=new ComponentManager(root,new Uri(UpdateTrust.Server),key,handler);var installed=manager.PrepareAsync(item,CancellationToken.None).GetAwaiter().GetResult();var next=Lock(bytes,"25.4.1");handler.Manifest=Sign(next);handler.Mode="interrupted";try{manager.PrepareAsync(next,CancellationToken.None).GetAwaiter().GetResult();throw new Exception("interrupted body accepted");}catch(IOException){} Require(File.ReadAllText(installed.EntryPoint)=="runtime","old runtime damaged");Require(manager.GetInstalled(next)==null,"partial runtime activated");Require(Directory.GetDirectories(Path.Combine(root,"components"),".staging-*").Length==0,"partial staging remains");});
} finally { Directory.Delete(temp,true); }
ComponentServerCases.Run(Test);
PlatformLaunchCases.Run(Test);
Console.WriteLine($"RESULT {passed} passed; {failed} failed"); return failed==0?0:1;

sealed class FakeHandler : HttpMessageHandler {
 public SignedComponentManifest Manifest; readonly byte[] archive; public bool Fail; public string Mode;
 public FakeHandler(SignedComponentManifest manifest, byte[] archive) { Manifest=manifest; this.archive=archive; }
 protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage request,CancellationToken cancellation) { if(Fail) throw new InvalidOperationException("offline"); var isManifest=request.RequestUri.AbsolutePath.EndsWith("/manifest"); if(!isManifest&&Mode=="redirect") return Task.FromResult(new HttpResponseMessage(HttpStatusCode.Redirect)); if(!isManifest&&Mode=="stall")return Task.FromResult(new HttpResponseMessage(HttpStatusCode.OK){Content=new StreamContent(new InterruptedStream(true))});if(!isManifest&&Mode=="interrupted")return Task.FromResult(new HttpResponseMessage(HttpStatusCode.OK){Content=new StreamContent(new InterruptedStream(false))});var content=isManifest?Encoding.UTF8.GetBytes(JsonWire.Serialize(Manifest)):Mode=="short"?archive.Take(5).ToArray():Mode=="oversize"?archive.Concat(new byte[5]).ToArray():Mode=="hash"?new byte[archive.Length]:archive; return Task.FromResult(new HttpResponseMessage(HttpStatusCode.OK) { Content=new ByteArrayContent(content) }); }
}
sealed class InterruptedStream(bool stall) : Stream {
 bool started;public override bool CanRead=>true;public override bool CanSeek=>false;public override bool CanWrite=>false;public override long Length=>throw new NotSupportedException();public override long Position{get=>throw new NotSupportedException();set=>throw new NotSupportedException();}public override void Flush()=>throw new NotSupportedException();public override long Seek(long offset,SeekOrigin origin)=>throw new NotSupportedException();public override void SetLength(long value)=>throw new NotSupportedException();public override void Write(byte[] buffer,int offset,int count)=>throw new NotSupportedException();public override int Read(byte[] buffer,int offset,int count)=>throw new NotSupportedException();
 public override async Task<int> ReadAsync(byte[] buffer,int offset,int count,CancellationToken cancellation){if(stall){await Task.Delay(Timeout.Infinite,cancellation);return 0;}if(!started){started=true;buffer[offset]=1;return 1;}throw new IOException("connection interrupted");}
}
